#include "../verifiable_ann_common.hpp"
#include <set>
#include <sstream>
namespace {
using namespace vann;
struct Config{std::string dataset="../dataset/sift",cache="../merkle_hnsw/sift100k_M16_efc100.index",output="relaxed_hnsw_harvest_sift100k.csv";int base=100000,queries=10,k=10,M=16,efc=100,upper_steps=4;std::vector<int>bits{4,6},beams{2,4,8},rounds{4,6,8,12,16};};
static std::vector<int> ints(const std::string&s){std::vector<int>o;std::stringstream ss(s);std::string x;while(std::getline(ss,x,','))if(!x.empty())o.push_back(std::stoi(x));return o;}
static Config args(int ac,char**av){Config c;for(int i=1;i<ac;++i){std::string a=av[i];auto v=[&](){if(++i==ac)throw std::runtime_error("missing value after "+a);return std::string(av[i]);};if(a=="--dataset")c.dataset=v();else if(a=="--cache")c.cache=v();else if(a=="--output")c.output=v();else if(a=="--base")c.base=std::stoi(v());else if(a=="--queries")c.queries=std::stoi(v());else if(a=="--k")c.k=std::stoi(v());else if(a=="--M")c.M=std::stoi(v());else if(a=="--ef-construction")c.efc=std::stoi(v());else if(a=="--upper-steps")c.upper_steps=std::stoi(v());else if(a=="--bits")c.bits=ints(v());else if(a=="--beams")c.beams=ints(v());else if(a=="--rounds")c.rounds=ints(v());else throw std::runtime_error("unknown option "+a);}return c;}
class NestedSQ{int d_;std::vector<float>lo_,span_;std::vector<uint8_t>code_;public:explicit NestedSQ(const HnswIndex&h):d_(h.dimension()),lo_(d_,INFINITY),span_(d_),code_(h.size()*d_){std::vector<float>hi(d_,-INFINITY);for(size_t id=0;id<h.size();++id)for(int j=0;j<d_;++j){lo_[j]=std::min(lo_[j],h.vector(id)[j]);hi[j]=std::max(hi[j],h.vector(id)[j]);}for(int j=0;j<d_;++j)span_[j]=hi[j]-lo_[j];for(size_t id=0;id<h.size();++id)for(int j=0;j<d_;++j){double u=span_[j]>0?(h.vector(id)[j]-lo_[j])/span_[j]:0;code_[id*d_+j]=uint8_t(std::clamp(int(std::floor(u*64)),0,63));}}
float score2(const float*q,int id,int bits)const{int bins=1<<bits,shift=6-bits;float s=0;for(int j=0;j<d_;++j){int p=code_[size_t(id)*d_+j]>>shift;float x=lo_[j]+span_[j]*((p+.5F)/bins),z=q[j]-x;s+=z*z;}return s;}
float lower2(const float*q,int id,int bits)const{int bins=1<<bits,shift=6-bits;float s=0;for(int j=0;j<d_;++j){int p=code_[size_t(id)*d_+j]>>shift;float a=std::nextafter(lo_[j]+span_[j]*(float(p)/bins),-INFINITY),b=std::nextafter(lo_[j]+span_[j]*(float(p+1)/bins),INFINITY);float z=q[j]<a?a-q[j]:(q[j]>b?q[j]-b:0);s+=z*z;}return std::nextafter(s,0.F);}double bytes(int bits)const{return std::ceil(d_*bits/8.0);}};
static size_t proof_count(size_t n,const std::vector<int>&sel){if(!n)return 0;size_t padded=1;while(padded<n)padded<<=1;std::vector<size_t>cur;for(int x:sel)if(x>=0&&size_t(x)<n)cur.push_back(x);std::sort(cur.begin(),cur.end());cur.erase(std::unique(cur.begin(),cur.end()),cur.end());if(cur.empty())return 1;size_t ans=0;while(padded>1){std::vector<size_t>up;for(size_t i=0;i<cur.size();){size_t x=cur[i];if(i+1<cur.size()&&cur[i+1]==(x^1U))i+=2;else{++ans;++i;}size_t p=x>>1;if(up.empty()||up.back()!=p)up.push_back(p);}cur.swap(up);padded>>=1;}return ans;}
struct Trace{std::vector<int>discovered,expanded,answer,refine,raw;std::vector<OpenedAdjacency>opened;int upper_expanded=0,level0_expanded=0;double routing_payload=0,routing_auth=0,verification_payload=0,verification_auth=0;};
static Trace search(const HnswIndex&h,const NestedSQ&sq,const float*q,int k,int bits,int beam,int rounds,int upper_steps){Trace t;size_t n=h.size();std::vector<uint8_t>seen(n),expanded_any(n),expanded0(n);std::vector<float>score(n,INFINITY);std::set<std::pair<float,int>>frontier;std::set<std::pair<int,int>>opened;
auto discover=[&](int id){if(!seen[id]){seen[id]=1;score[id]=sq.score2(q,id,bits);frontier.insert({score[id],id});}};
auto expand=[&](int id,int level){if(!opened.insert({id,level}).second)return std::vector<int>{};if(!expanded_any[id]){expanded_any[id]=1;t.expanded.push_back(id);}t.opened.push_back({id,level});return h.neighbors(id,level);};
int entry=h.index->hnsw.entry_point;discover(entry);for(int level=h.index->hnsw.max_level;level>0;--level)for(int step=0;step<upper_steps;++step){int next=entry;float best=score[entry];auto ns=expand(entry,level);if(ns.empty())break;for(int id:ns){discover(id);if(score[id]<best||(score[id]==best&&id<next)){best=score[id];next=id;}}if(next==entry)break;entry=next;}
frontier.clear();for(size_t id=0;id<n;++id)if(seen[id]&&!expanded0[id])frontier.insert({score[id],int(id)});for(int round=0;round<rounds&&!frontier.empty();++round){std::vector<int>batch;for(int j=0;j<beam&&!frontier.empty();++j){auto it=frontier.begin();batch.push_back(it->second);frontier.erase(it);}for(int id:batch){if(expanded0[id])continue;expanded0[id]=1;++t.level0_expanded;for(int nb:expand(id,0)){bool fresh=!seen[nb];discover(nb);if(fresh&&!expanded0[nb])frontier.insert({score[nb],nb});}}}
for(size_t id=0;id<n;++id)if(seen[id])t.discovered.push_back(id);t.upper_expanded=int(t.expanded.size())-t.level0_expanded;std::vector<DistanceId>exact;for(int id:t.discovered)exact.push_back({squared_l2(q,h.vector(id),h.dimension()),id});if(exact.size()<size_t(k))throw std::runtime_error("candidate set smaller than k");std::partial_sort(exact.begin(),exact.begin()+k,exact.end(),better);exact.resize(k);float tau2=exact.back().distance;for(auto z:exact)t.answer.push_back(z.id);std::vector<uint8_t>answer(n);for(int id:t.answer)answer[id]=1;for(int id:t.discovered)if(sq.lower2(q,id,4)<=tau2){t.refine.push_back(id);if(answer[id]||sq.lower2(q,id,6)<=tau2)t.raw.push_back(id);}
std::sort(t.expanded.begin(),t.expanded.end());std::sort(t.opened.begin(),t.opened.end(),[](auto a,auto b){return a.local_id<b.local_id||(a.local_id==b.local_id&&a.level<b.level);});t.routing_payload=32+t.discovered.size()*(4+sq.bytes(bits));t.routing_auth=proof_count(n,t.discovered)*32.0;for(int id:t.expanded){t.routing_payload+=8;int levels=h.index->hnsw.levels[id];for(int level=0;level<levels;++level){t.routing_payload+=5;if(opened.count({id,level}))t.routing_payload+=h.neighbors(id,level).size()*4.0;else t.routing_auth+=32;}}t.routing_auth+=proof_count(n,t.expanded)*32.0;std::vector<int>sq6only;if(bits==4){std::set_difference(t.refine.begin(),t.refine.end(),t.raw.begin(),t.raw.end(),std::back_inserter(sq6only));t.verification_payload+=sq6only.size()*(4+sq.bytes(6));if(!sq6only.empty())t.verification_auth+=proof_count(n,sq6only)*32.0;}t.verification_payload+=t.raw.size()*(4+h.dimension()*sizeof(float));if(!t.raw.empty())t.verification_auth+=proof_count(n,t.raw)*32.0;return t;}
static std::vector<std::vector<int>> ground_truth(const HnswIndex&h,const Matrix&q,int k){std::vector<std::vector<int>>gt(q.rows());for(size_t qi=0;qi<q.rows();++qi){std::vector<DistanceId>all;all.reserve(h.size());for(size_t id=0;id<h.size();++id)all.push_back({squared_l2(q.row(qi),h.vector(id),h.dimension()),int(id)});std::partial_sort(all.begin(),all.begin()+k,all.end(),better);for(int j=0;j<k;++j)gt[qi].push_back(all[j].id);}return gt;}
}
int main(int ac,char**av)try{using namespace vann;Config c=args(ac,av);std::cerr<<"Loading SIFT100K and original cached HNSW...\n";Matrix base=read_fvecs(c.dataset+"/sift_base.fvecs",c.base),queries=read_fvecs(c.dataset+"/sift_query.fvecs",c.queries);HnswIndex h=build_hnsw(base,c.M,c.efc,c.cache);base.values.clear();base.values.shrink_to_fit();std::cerr<<"Computing exact GT and nested SQ6...\n";auto gt=ground_truth(h,queries,c.k);NestedSQ sq(h);std::ofstream out(c.output);if(!out)throw std::runtime_error("cannot write "+c.output);out<<"bits,beam_width,rounds,fixed_level0_budget,recall_at_10,avg_expanded_nodes,avg_upper_expanded,avg_level0_expanded,avg_discovered,avg_harvested_unexpanded,avg_sq6_refined,avg_raw_vectors,routing_payload_bytes,routing_auth_bytes,routing_vo_bytes,candidate_payload_bytes,candidate_auth_bytes,candidate_verification_vo_bytes,total_vo_bytes,total_vo_kib\n";
for(int bits:c.bits)for(int beam:c.beams)for(int rounds:c.rounds){if((bits!=4&&bits!=6)||beam<1||rounds<1)continue;double hits=0,expanded=0,upper=0,level0=0,discovered=0,refined=0,raw=0,rp=0,ra=0,vp=0,va=0;for(int qi=0;qi<c.queries;++qi){Trace t=search(h,sq,queries.row(qi),c.k,bits,beam,rounds,c.upper_steps);std::unordered_set<int>answer(t.answer.begin(),t.answer.end());for(int id:gt[qi])hits+=answer.count(id);expanded+=t.expanded.size();upper+=t.upper_expanded;level0+=t.level0_expanded;discovered+=t.discovered.size();refined+=t.refine.size();raw+=t.raw.size();rp+=t.routing_payload;ra+=t.routing_auth;vp+=t.verification_payload;va+=t.verification_auth;}double nq=c.queries,route=(rp+ra)/nq,verify=(vp+va)/nq,total=route+verify;out<<bits<<','<<beam<<','<<rounds<<','<<beam*rounds<<','<<hits/(nq*c.k)<<','<<expanded/nq<<','<<upper/nq<<','<<level0/nq<<','<<discovered/nq<<','<<(discovered-expanded)/nq<<','<<refined/nq<<','<<raw/nq<<','<<rp/nq<<','<<ra/nq<<','<<route<<','<<vp/nq<<','<<va/nq<<','<<verify<<','<<total<<','<<total/1024<<'\n';std::cout<<"SQ"<<bits<<" b="<<beam<<" r="<<rounds<<" recall="<<std::fixed<<std::setprecision(3)<<hits/(nq*c.k)<<" exp="<<expanded/nq<<" cand="<<discovered/nq<<" raw="<<raw/nq<<" route="<<route/1024<<"KiB verify="<<verify/1024<<"KiB total="<<total/1024<<"KiB\n";}std::cerr<<"Wrote "<<c.output<<'\n';return 0;}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<'\n';return 1;}
